    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
        javax.swing.JOptionPane.showMessageDialog(this, "Capturando rostro...");

    // Hilo para simular proceso sin congelar la interfaz
    new Thread(new Runnable() {
        public void run() {
            try {
              // Espera 5 segundos (simulación)
           Thread.sleep(5000);

                // Volver al hilo gráfico
            javax.swing.SwingUtilities.invokeLater(new Runnable() {
             public void run() {
         javax.swing.JOptionPane.showMessageDialog(null, "Rostro verificado correctamente");

            MenuPrincipal m = new MenuPrincipal(clienteId);
            m.setVisible(true);
            dispose();

              }
             });

         } catch (InterruptedException e) {
           e.printStackTrace();
            }
        }
    }).start();
    }//GEN-LAST:event_jButton1ActionPerformed

